import sys
parts = sys.stdin.read().split()
if len(parts) >= 2:
    oxygen = int(parts[0])
    power = int(parts[1])
    if oxygen >= 80 and power >= 50:
        print("STABLE")
    else:
        print("CRITICAL")

import sys
lines = sys.stdin.read().strip().split('\n')
if len(lines) >= 2:
    pairs = lines[0].split()
    query = lines[1].strip()
    data = {}
    for pair in pairs:
        if ':' in pair:
            k, v = pair.split(':', 1)
            data[k] = v
    print(data.get(query, "NOT FOUND"))
